/* Export the original-timing recipe for comparison with recorded accepted keyframes.
 * Expectations are not regenerated by the implementation under test. */
#include "combo/render/DinsFireRemake.h"
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int fireFrame;
    float phase;
    CwDinsVec hand;
} NativeVisualCase;
#include "native_visual_cases.inc"

int main(void) {
#ifndef CW_DINS_NATIVE_RENDERER
    CwDinsMesh mesh;
    CwDinsFireRemake_BuildShell(&mesh, 20, .364362478f, 1, 0, (CwDinsVec){ 1, 0, 0 }, (CwDinsVec){ 0, 1, 0 }, 0xFFC800,
                                0xFF0000);
    fprintf(stderr, "FAIL accepted native ribbons require at least 590 quads; production emitted %zu\n", mesh.count);
    return mesh.count >= 590 ? 0 : 1;
#else
    const float views[][2] = { { 0, 11 }, { 18, 16 }, { -55, 29 } };
    for (size_t sample = 0; sample < sizeof(cases) / sizeof(cases[0]); ++sample) {
        for (size_t view = 0; view < sizeof(views) / sizeof(views[0]); ++view) {
            float az = views[view][0] * .017453292519943295f;
            float el = views[view][1] * .017453292519943295f;
            CwDinsVec right = { cosf(az), 0, -sinf(az) };
            CwDinsVec up = { -sinf(az) * sinf(el), cosf(el), -cosf(az) * sinf(el) };
            CwDinsMesh mesh;
            if (cases[sample].fireFrame < 0)
                CwDinsFireRemake_BuildNativeCharge(&mesh, cases[sample].phase, cases[sample].hand, right, up, 0xFFC800,
                                                   0xFF0000);
            else
                CwDinsFireRemake_BuildFireRecipe(&mesh, cases[sample].fireFrame, 40, 12, right, up, 0xFFC800, 0xFF0000);
            printf("{\"sample\":%zu,\"view\":%zu,\"mesh\":[", sample, view);
            for (size_t index = 0; index < mesh.count; ++index) {
                CwDinsQuad* q = &mesh.quads[index];
                printf("%s{\"p\":[", index ? "," : "");
                for (int v = 0; v < 4; ++v)
                    printf("%s[%.8g,%.8g,%.8g]", v ? "," : "", q->p[v].x, q->p[v].y, q->p[v].z);
                printf("],\"s\":%.8g,\"t\":%.8g,\"sSpan\":%.8g,\"tSpan\":%.8g,"
                       "\"primary\":%u,\"secondary\":%u,\"alpha\":[%u,%u,%u,%u],"
                       "\"spark\":%u,\"band\":%u,\"burnFrame\":%u,\"burn\":%.8g}",
                       q->s, q->t, q->sSpan, q->tSpan, q->primary, q->secondary, q->alpha[0], q->alpha[1], q->alpha[2],
                       q->alpha[3], q->spark, q->band, q->burnFrame, q->burn);
            }
            puts("]}");
        }
    }
    return 0;
#endif
}
